rules.cssText:
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}

@media (prefers-reduced-motion: reduce) {
  .wf-marq .marq { overflow: visible; mask-image: none; padding: 0px 28px; }
  .wf-marq .marq-track { animation: auto ease 0s 1 normal none running none; transform: none; display: flex; flex-wrap: wrap; justify-content: center; white-space: normal; gap: 10px 14px; padding-left: 0px; }
  .wf-marq .marq-track i { display: none; }
  .wf-marq .marq-track span { font-family: var(--mm-sans,'Neue Haas Grotesk Display Pro',Helvetica,sans-serif); font-size: 0.72rem; line-height: 1; letter-spacing: 0.07em; text-transform: uppercase; border: 1px solid var(--line-soft); border-radius: 999px; padding: 8px 10px; background: rgba(251, 250, 247, 0.44); }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .wf * { transition: none !important; animation: auto ease 0s 1 normal none running none !important; scroll-behavior: auto !important; }
}

@media (prefers-reduced-motion: reduce) {
  html:focus-within { scroll-behavior: auto; }
  *, ::before, ::after { animation-duration: var(--mm-motion-reduced) !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: var(--mm-motion-reduced) !important; }
}

@media (prefers-reduced-motion: reduce) {
  body.motion-on [data-reveal] { opacity: 1 !important; transform: none !important; transition: none !important; }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}

@media (prefers-reduced-motion: reduce) {
  .sp * { transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
}

@media (prefers-reduced-motion: reduce) {
  html:focus-within { scroll-behavior: auto; }
  *, ::before, ::after { animation-duration: var(--mm-motion-reduced) !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: var(--mm-motion-reduced) !important; }
}
